mapper.update:
UPDATE review
SET REVIEW_CONTENT = #{reviewContent},
    THUMBS_UP = #{thumbsUp}
WHERE REVIEW_ID = #{reviewId}

mapper.delete:
DELETE FROM review
WHERE REVIEW_ID = #{reviewId}
  AND (ID = #{requesterId} OR #{requesterId} = 'Admin')

mapper.select:
SELECT * FROM review
WHERE RECIPE_CODE = #{RECIPE_CODE}
ORDER BY REG_DATE DESC

SELECT * FROM review
WHERE ID = #{ID}
ORDER BY REG_DATE DESC
